/**
 * MYBC Jackpot Widget
 * Two-state image widget: Closed (with arrows) / Expanded (without).
 * Sits under the header, overlays content.
 */
(function () {
  "use strict";

  var IMG_CLOSED   = "data:image/png;base64,";
  var IMG_EXPANDED = "data:image/png;base64,";

  var CLOSED_W = 375, CLOSED_H = 79;
  var EXPANDED_W = 375, EXPANDED_H = 73;
  var TIP_H = 28; /* height of visible tip when collapsed */

  var DEFAULTS = {
    containerId: null,
    onOptIn: null,
    onOptOut: null,
    onTerms: null
  };

  var STORAGE_KEY = "jackpot_mybc_optin";
  var P = "jw-mybc-";

  function injectStyles() {
    if (document.getElementById(P + "styles")) return;
    var css = [
      "." + P + "wrap { width:100%; position:absolute; left:0; z-index:99999; display:flex; justify-content:center; font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif; user-select:none; -webkit-user-select:none; }",

      "." + P + "inner { position:relative; overflow:hidden; transition:height 0.25s ease; }",
      "." + P + "img { display:block; image-rendering:auto; -webkit-backface-visibility:hidden; transform:translateZ(0); cursor:pointer; }",

      /* opt-in button hit area */
      "." + P + "opt-btn { position:absolute; top:10%; right:52px; width:70px; height:80%; cursor:pointer; background:transparent; border:none; z-index:5; }",

      /* hamburger hit area */
      "." + P + "menu-btn { position:absolute; top:0; right:0; width:50px; height:100%; cursor:pointer; z-index:5; }",

      /* arrows hit area — bottom center of closed image */
      "." + P + "arrows-btn { position:absolute; bottom:0; left:50%; transform:translateX(-50%); width:80px; height:20px; cursor:pointer; z-index:5; }",

      /* popup menu */
      "." + P + "popup { display:none; position:absolute; top:100%; right:0; margin-top:4px; background:#1a0a35; border:1.5px solid rgba(184,134,11,0.5); border-radius:10px; padding:6px; z-index:10; box-shadow:0 4px 20px rgba(0,0,0,0.6); min-width:44px; }",
      "." + P + "popup." + P + "open { display:flex; flex-direction:column; gap:4px; }",

      "." + P + "mi { display:flex; align-items:center; gap:8px; padding:0 10px; margin:0; border:none; background:transparent; color:#ddd; font-size:12px; font-weight:600; cursor:pointer; border-radius:8px; white-space:nowrap; min-height:44px; min-width:44px; transition:background 0.15s; }",
      "." + P + "mi:hover { background:rgba(255,255,255,0.08); }",
      "." + P + "mi:active { background:rgba(255,255,255,0.14); }",
      "." + P + "mi-icon { width:20px; height:20px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }",
      "." + P + "mi-icon svg { width:18px; height:18px; }",
      "." + P + "mi-close svg { stroke:#ff6b6b; }",
      "." + P + "mi-terms svg { stroke:#8cb4ff; }",

      /* T&C modal */
      "." + P + "overlay { display:none; position:fixed; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.7); z-index:1000000; align-items:center; justify-content:center; padding:20px; }",
      "." + P + "overlay." + P + "open { display:flex; }",
      "." + P + "modal { background:#1a0a35; border:1.5px solid rgba(184,134,11,0.5); border-radius:14px; width:100%; max-width:360px; max-height:80vh; display:flex; flex-direction:column; overflow:hidden; }",
      "." + P + "modal-header { display:flex; align-items:center; justify-content:space-between; padding:14px 16px; border-bottom:1px solid rgba(184,134,11,0.25); flex-shrink:0; }",
      "." + P + "modal-title { font-size:14px; font-weight:700; color:#daa520; letter-spacing:0.5px; }",
      "." + P + "modal-x { width:36px; height:36px; display:flex; align-items:center; justify-content:center; border:none; background:transparent; cursor:pointer; border-radius:8px; transition:background 0.15s; }",
      "." + P + "modal-x:hover { background:rgba(255,255,255,0.08); }",
      "." + P + "modal-x svg { width:18px; height:18px; stroke:#ff6b6b; }",
      "." + P + "modal-body { padding:16px; overflow-y:auto; -webkit-overflow-scrolling:touch; flex:1; }",
      "." + P + "modal-body p { font-size:12px; line-height:1.7; color:#bbb; margin-bottom:12px; }",
      "." + P + "modal-body p:last-child { margin-bottom:0; }",
      "." + P + "modal-body strong { color:#ddd; }"
    ];

    var style = document.createElement("style");
    style.id = P + "styles";
    style.textContent = css.join("\n");
    document.head.appendChild(style);
  }

  var SVG_TERMS = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="8" y1="13" x2="16" y2="13"/><line x1="8" y1="17" x2="16" y2="17"/></svg>';
  var SVG_CLOSE = '<svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round"><line x1="6" y1="6" x2="18" y2="18"/><line x1="18" y1="6" x2="6" y2="18"/></svg>';

  function makeItem(cls, svgStr, label) {
    var btn = document.createElement("button");
    btn.className = P + "mi " + P + cls;
    var icon = document.createElement("span");
    icon.className = P + "mi-icon";
    icon.innerHTML = svgStr;
    btn.appendChild(icon);
    var txt = document.createElement("span");
    txt.textContent = label;
    btn.appendChild(txt);
    return btn;
  }

  function buildWidget() {
    var el = document.createElement("div");
    el.className = P + "wrap";

    var inner = document.createElement("div");
    inner.className = P + "inner";

    var img = document.createElement("img");
    img.className = P + "img";
    img.draggable = false;
    inner.appendChild(img);

    /* opt-in hit area */
    var optBtn = document.createElement("button");
    optBtn.className = P + "opt-btn";
    inner.appendChild(optBtn);

    /* hamburger hit area */
    var menuBtn = document.createElement("div");
    menuBtn.className = P + "menu-btn";
    inner.appendChild(menuBtn);

    /* arrows hit area (only active in closed/expanded-with-arrows state) */
    var arrowsBtn = document.createElement("div");
    arrowsBtn.className = P + "arrows-btn";
    inner.appendChild(arrowsBtn);

    /* popup */
    var popup = document.createElement("div");
    popup.className = P + "popup";
    popup.appendChild(makeItem("mi-terms", SVG_TERMS, "T&C"));
    popup.appendChild(makeItem("mi-close", SVG_CLOSE, "Close"));
    inner.appendChild(popup);

    el.appendChild(inner);

    /* T&C modal */
    var overlay = document.createElement("div");
    overlay.className = P + "overlay";
    var modal = document.createElement("div");
    modal.className = P + "modal";
    var mHeader = document.createElement("div");
    mHeader.className = P + "modal-header";
    var mTitle = document.createElement("div");
    mTitle.className = P + "modal-title";
    mTitle.textContent = "Terms & Conditions";
    mHeader.appendChild(mTitle);
    var mX = document.createElement("button");
    mX.className = P + "modal-x";
    mX.innerHTML = SVG_CLOSE;
    mHeader.appendChild(mX);
    modal.appendChild(mHeader);
    var mBody = document.createElement("div");
    mBody.className = P + "modal-body";
    mBody.innerHTML = "<p><strong>MYBC Jackpot</strong></p>" +
      "<p>The MYBC Jackpot is a progressive jackpot that increases with each qualifying bet placed by participating players.</p>" +
      "<p><strong>Eligibility</strong></p>" +
      "<p>To participate, players must opt in by clicking the OPT-IN button. Players can opt out at any time.</p>" +
      "<p><strong>Winning</strong></p>" +
      "<p>The jackpot is awarded randomly to one opted-in player. The probability of winning increases proportionally with the size of qualifying bets.</p>" +
      "<p><strong>General</strong></p>" +
      "<p>Standard wagering terms apply. The operator reserves the right to modify or cancel this promotion at any time. Must be 18+ to participate. Please gamble responsibly.</p>";
    modal.appendChild(mBody);
    overlay.appendChild(modal);
    el.appendChild(overlay);

    return el;
  }

  function getOptIn() {
    try { return localStorage.getItem(STORAGE_KEY) === "1"; } catch (_) { return false; }
  }
  function setOptIn(val) {
    try { localStorage.setItem(STORAGE_KEY, val ? "1" : "0"); } catch (_) {}
  }

  function createController(cfg) {
    injectStyles();
    var widget = buildWidget();
    var optedIn = getOptIn();
    var expanded = false;
    var menuOpen = false;

    var img       = widget.querySelector("." + P + "img");
    var optBtn    = widget.querySelector("." + P + "opt-btn");
    var menuBtn   = widget.querySelector("." + P + "menu-btn");
    var arrowsBtn = widget.querySelector("." + P + "arrows-btn");
    var popup     = widget.querySelector("." + P + "popup");
    var miTerms   = popup.children[0];
    var miClose   = popup.children[1];
    var tcOverlay = widget.querySelector("." + P + "overlay");
    var tcX       = tcOverlay.querySelector("." + P + "modal-x");

    function render() {
      var inner = widget.querySelector("." + P + "inner");
      if (expanded) {
        /* full bar with arrows visible */
        img.src = IMG_CLOSED;
        img.style.width = CLOSED_W + "px";
        img.style.height = CLOSED_H + "px";
        img.style.marginTop = "0";
        inner.style.height = CLOSED_H + "px";
        arrowsBtn.style.display = "block";
        optBtn.style.display = "block";
        menuBtn.style.display = "block";
      } else {
        /* only bottom tip peeks out */
        img.src = IMG_CLOSED;
        img.style.width = CLOSED_W + "px";
        img.style.height = CLOSED_H + "px";
        img.style.marginTop = -(CLOSED_H - TIP_H) + "px";
        inner.style.height = TIP_H + "px";
        arrowsBtn.style.display = "block";
        optBtn.style.display = "none";
        menuBtn.style.display = "none";
      }
      closeMenu();
    }

    function setExpanded(val) {
      expanded = val;
      render();
    }

    function closeMenu() {
      menuOpen = false;
      popup.classList.remove(P + "open");
    }
    function toggleMenu() {
      menuOpen = !menuOpen;
      if (menuOpen) popup.classList.add(P + "open");
      else popup.classList.remove(P + "open");
    }

    function openTerms() { tcOverlay.classList.add(P + "open"); }
    function closeTerms() { tcOverlay.classList.remove(P + "open"); }

    /* arrows — toggle expand/collapse */
    arrowsBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      setExpanded(!expanded);
    });

    /* clicking the closed image also expands */
    img.addEventListener("click", function () {
      if (!expanded) setExpanded(true);
    });

    /* opt in/out */
    optBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      optedIn = !optedIn;
      setOptIn(optedIn);
      if (optedIn && typeof cfg.onOptIn === "function") cfg.onOptIn();
      if (!optedIn && typeof cfg.onOptOut === "function") cfg.onOptOut();
    });

    /* hamburger */
    menuBtn.addEventListener("click", function (e) {
      e.stopPropagation();
      toggleMenu();
    });

    /* menu items */
    miTerms.addEventListener("click", function (e) {
      e.stopPropagation();
      closeMenu();
      openTerms();
      if (typeof cfg.onTerms === "function") cfg.onTerms();
    });
    miClose.addEventListener("click", function (e) {
      e.stopPropagation();
      closeMenu();
      setExpanded(false);
    });

    /* T&C modal */
    tcX.addEventListener("click", function (e) {
      e.stopPropagation();
      closeTerms();
    });
    tcOverlay.addEventListener("click", function (e) {
      if (e.target === tcOverlay) closeTerms();
    });

    /* close menu on outside click */
    document.addEventListener("click", function () {
      if (menuOpen) closeMenu();
    });

    function mount() {
      var container = null;
      if (cfg.containerId) {
        container = document.getElementById(cfg.containerId);
      }
      if (!container) {
        var firstChild = document.body.firstElementChild;
        var headerH = firstChild ? firstChild.offsetHeight : 0;
        widget.style.top = headerH + "px";
        if (firstChild && firstChild.nextElementSibling) {
          document.body.insertBefore(widget, firstChild.nextElementSibling);
        } else {
          document.body.appendChild(widget);
        }
      } else {
        container.appendChild(widget);
      }
      render();
    }

    return {
      mount: mount,
      destroy: function () {
        if (widget.parentNode) widget.parentNode.removeChild(widget);
      },
      isOptedIn: function () { return optedIn; },
      expand: function () { setExpanded(true); },
      collapse: function () { setExpanded(false); }
    };
  }

  window.JackpotMybcWidget = {
    init: function (userConfig) {
      var cfg = {};
      for (var k in DEFAULTS) {
        if (DEFAULTS.hasOwnProperty(k)) {
          cfg[k] = userConfig && userConfig.hasOwnProperty(k) ? userConfig[k] : DEFAULTS[k];
        }
      }
      var ctrl = createController(cfg);
      if (document.readyState === "complete" || document.readyState === "interactive") {
        ctrl.mount();
      } else {
        document.addEventListener("DOMContentLoaded", function () { ctrl.mount(); });
      }
      return ctrl;
    }
  };
})();
